import {RELEASE,readBackup,validateInventory,backupText,shoppingCSV,restock} from './beta.mjs';
import {getBeepVolume,setBeepVolume,armFeedback,beep} from './assist.mjs';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function downloadText(text,name,type='application/json'){const url=URL.createObjectURL(new Blob([text],{type})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
export function dataSettings({getDB,exportData,getLegacy,getMode,restoreData,getRecovery,modal,close,toast,device,onActor}){
const $=s=>document.querySelector(s),mode=getMode(),label=mode==='real'?'inventario real':'pruebas',last=localStorage.getItem('mt-last-export-'+mode),actor=localStorage.getItem('mtOperator')||'';
$('#content').innerHTML=`<div class="settings-grid"><section class="panel"><span class="eyebrow">PROTEGE TU TRABAJO</span><h2>Copias de seguridad</h2><p>Inventario activo: <b>${label}</b>. Guarda una copia fuera del navegador para poder recuperarla o trasladarla a otro equipo.</p><p id="backupState">${last?'Última exportación: '+new Date(last).toLocaleString('es-SV'):'Todavía no has exportado una copia de este inventario.'}</p><button id="exportBackup" class="primary">Descargar copia completa</button><label class="import-label">Restaurar desde una copia JSON<input id="restoreFile" type="file" accept=".json,application/json"></label><button id="recoverLocal">Subir inventario anterior de este dispositivo</button><p class="small">Si tenías productos antes de Beta 1P, revisa esta copia antes de subirla. Reemplazará el inventario activo en la nube; no se mezclan copias automáticamente.</p></section><section class="panel"><h2>Quién registra</h2><p>Este nombre aparecerá en los nuevos movimientos. No es una cuenta de usuario.</p><label>Nombre o encargado<input id="actorName" value="${esc(actor)}" maxlength="50" placeholder="Tu nombre"></label><button id="saveActor">Guardar nombre</button><h3>Sonido del escáner</h3><label>Volumen: <span id="volumeLabel">${Math.round(getBeepVolume()*100)}%</span><input id="beepVolume" type="range" min="0" max="100" value="${Math.round(getBeepVolume()*100)}"></label><button id="testSound">Probar bip de caja</button><p class="small">El volumen del dispositivo y el modo silencio también influyen.</p></section><section class="panel"><h2>Mi Torno Gestión · Beta 1P</h2><p>Versión ${RELEASE}. Inventario real compartido en la nube, con copias completas descargables.</p><p>En el teléfono vinculado puedes consultar el inventario y confirmar movimientos. Para usar la cámara vinculada, ambas pantallas deben estar abiertas.</p><button id="showGuide">Guía rápida</button></section></div>`;
$('#exportBackup').onclick=async()=>{try{downloadText(backupText(await exportData(),getMode(),device),'Mi-Torno-'+getMode()+'-'+new Date().toISOString().replace(/[:.]/g,'-')+'.json');const at=new Date().toISOString();localStorage.setItem('mt-last-export-'+getMode(),at);$('#backupState').textContent='Copia descargada. Guárdala fuera del navegador.';toast('Copia exportada')}catch(e){toast(e.message)}};
function preview(data,title){const db=getDB();modal(`<h2>${title}</h2><p>Se reemplazará únicamente <b>${label}</b> en todos los dispositivos. El otro inventario se conserva.</p><div class="restore-summary"><b>${data.products.length} productos</b><span>${data.products.reduce((n,p)=>n+p.qty,0)} unidades</span><span>${data.events.length} movimientos</span></div><p>Actualmente tienes ${db.products.length} productos. Puedes descargar tu copia actual antes de continuar.</p><button type="button" id="exportBeforeRestore">Descargar copia actual</button><label class="check-label"><input id="acceptRestore" type="checkbox"> Reemplazar ${label} con esta copia</label><button type="button" id="confirmRestore" class="primary" disabled>Restaurar copia</button>`);$('#exportBeforeRestore').onclick=$('#exportBackup').onclick;$('#acceptRestore').onchange=e=>$('#confirmRestore').disabled=!e.target.checked;$('#confirmRestore').onclick=async()=>{if(!$('#acceptRestore').checked)return;try{await restoreData(data);close();toast('Copia restaurada en '+label)}catch(e){toast(e.message)}}}
$('#restoreFile').onchange=async e=>{const file=e.target.files[0];if(!file)return;try{if(file.size>16000000)throw Error('La copia supera 16 MB.');const result=readBackup(await file.text(),getMode());preview(result.data,'Revisar copia antes de restaurar')}catch(error){toast(error.message)}finally{e.target.value=''}};
$('#recoverLocal').onclick=()=>{try{const raw=getLegacy();if(!raw)throw Error('No hay inventario anterior guardado en este dispositivo.');preview(validateInventory(JSON.parse(raw)),'Revisar inventario anterior del dispositivo')}catch(e){toast(e.message)}};
$('#saveActor').onclick=()=>{const name=$('#actorName').value.trim();localStorage.setItem('mtOperator',name);onActor(name);toast(name?'Responsable actualizado':'Responsable sin identificar')};$('#beepVolume').oninput=e=>{setBeepVolume(Number(e.target.value)/100);$('#volumeLabel').textContent=e.target.value+'%'};$('#testSound').onclick=()=>{armFeedback();beep()};$('#showGuide').onclick=()=>showGuide(modal);
}
export function showGuide(modal){modal('<span class="eyebrow">GUÍA RÁPIDA</span><h2>Mi Torno Gestión · Beta 1P</h2><ol class="guide-list"><li><b>Registra productos.</b> Agrega código, foto, cantidad y ubicación.</li><li><b>Escanea y mueve.</b> Entrada de 3 → quedan 8. Salida de 6 → quedan 2 y aparece en Reposición.</li><li><b>Cuenta.</b> Registra el total contado y su motivo; revisa el historial.</li><li><b>Vincula el teléfono.</b> En la principal, Vincular escáner. En el teléfono, Vincular como escáner. Prueba código, foto e Inventario conectado.</li><li><b>Exporta una copia.</b> En Datos y ajustes puedes descargarla y restaurarla después.</li></ol><p>La cámara vinculada necesita ambas páginas abiertas. Para consultar y registrar inventario, cada dispositivo se conecta directamente al guardado compartido. Sin internet no se confirman movimientos.</p>')}
export function restockView(products,onOpen){const $=s=>document.querySelector(s),items=restock(products);$('#content').innerHTML=`<section class="panel restock-intro"><div><h2>Lista de reposición</h2><p>Productos en mínimo o por debajo. La compra sugerida usa el stock deseado; puedes ajustarlo en cada ficha.</p></div><button id="exportShopping" ${items.length?'':'disabled'}>Descargar lista de compra</button></section><div class="restock-list">${items.map(p=>`<article class="restock-row"><div><span class="code">${esc(p.code)}</span><h3>${esc(p.name)}</h3><p>${esc([p.shelf,p.level,p.box].filter(Boolean).join(' / ')||'Sin ubicación')}</p></div><div class="restock-numbers"><span>Disponible <b>${p.qty}</b></span><span>Objetivo <b>${p.target}</b></span><span class="buy-number">Comprar <b>${p.buy}</b></span></div><button data-restock="${esc(p.id)}">Registrar entrada</button></article>`).join('')||'<div class="empty"><h3>Todo por encima del mínimo</h3><p>Los productos que necesiten reposición aparecerán aquí.</p></div>'}</div>`;$('#exportShopping').onclick=()=>downloadText(shoppingCSV(products),'Mi-Torno-lista-de-compra.csv','text/csv;charset=utf-8');document.querySelectorAll('[data-restock]').forEach(button=>button.onclick=()=>onOpen(button.dataset.restock,'in'))}
